#include <cstdio>
#include <cctype>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

typedef pair<int, int> point;

const int INF_CONST = 1000000000;
const int MAX_SIZE = 11;
const int MAX_NODES = 205;
const int DIRECTIONS_COUNT = 4;
const int dy[DIRECTIONS_COUNT] = {-1, 0, 1, 0};
const int dx[DIRECTIONS_COUNT] = {0, -1, 0, 1};

int n, t;
char grid[MAX_SIZE][MAX_SIZE], backup[MAX_SIZE][MAX_SIZE];
int start_i, start_j;
int dist_b[MAX_SIZE][MAX_SIZE];
int dist_bk[MAX_SIZE][MAX_SIZE];
bool can_reach[MAX_SIZE][MAX_SIZE];
int total_nodes;
int cap[MAX_SIZE][MAX_SIZE];
vector<int> adj_list[MAX_NODES];
int flow[MAX_NODES], parent[MAX_NODES];

void first_bfs()
{
    fill((int*)cap, (int*)cap + MAX_SIZE * MAX_SIZE, t);
    cap[start_i][start_j] = 0;
    queue<point> q; q.push(point(start_i, start_j));
    while (!q.empty()) {
        point v = q.front(); int d = cap[v.first][v.second]; q.pop();
        for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
            point u = point(v.first + dy[dir], v.second + dx[dir]);
            if (0 <= u.first && u.first < n && 0 <= u.second && u.second < n && grid[u.first][u.second] != 'Y' && d + 1 < cap[u.first][u.second])
                cap[u.first][u.second] = d + 1, q.push(u);
        }
    }
}

void second_bfs(int sr, int sc)
{
    fill((int*)dist_bk, (int*)dist_bk + MAX_SIZE * MAX_SIZE, INF_CONST);
    dist_bk[sr][sc] = 0;
    fill((bool*)can_reach, (bool*)can_reach + MAX_SIZE * MAX_SIZE, false);
    can_reach[sr][sc] = true;
    queue<point> q; q.push(point(sr, sc));
    while (!q.empty()) {
        point v = q.front(); int d = dist_bk[v.first][v.second]; q.pop();
        can_reach[v.first][v.second] = d <= cap[v.first][v.second];
        if (d >= cap[v.first][v.second]) continue;
        for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
            point u = point(v.first + dy[dir], v.second + dx[dir]);
            if (0 <= u.first && u.first < n && 0 <= u.second && u.second < n && grid[u.first][u.second] != 'Y' && d + 1 < dist_bk[u.first][u.second])
                dist_bk[u.first][u.second] = d + 1, q.push(u);
        }
    }
}

void run_bfs(int sr, int sc, int d[][MAX_SIZE], int INF_VAL)
{
    fill((int*)d, (int*)d + MAX_SIZE * MAX_SIZE, INF_VAL);
    d[sr][sc] = 0;
    queue<point> q; q.push(point(sr, sc));
    while (!q.empty()) {
        point v = q.front(); int d_v = d[v.first][v.second]; q.pop();
        for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
            point u = point(v.first + dy[dir], v.second + dx[dir]);
            if (0 <= u.first && u.first < n && 0 <= u.second && u.second < n && grid[u.first][u.second] != 'Y' && d_v + 1 < d[u.first][u.second])
                d[u.first][u.second] = d_v + 1, q.push(u);
        }
    }
}

int max_flow()
{
    fill(flow, flow + total_nodes, 0); flow[0] = INF_CONST;
    priority_queue<point> pq; pq.push(point(INF_CONST, 0));
    while (!pq.empty()) {
        int v = pq.top().second, f = pq.top().first; pq.pop();
        if (flow[v] != f) continue;
        for (size_t i = 0; i < adj_list[v].size(); i++) {
            int u = adj_list[v][i];
            if (min(f, cap[v][u]) > flow[u]) flow[u] = min(f, cap[v][u]), parent[u] = v, pq.push(point(flow[u], u));
        }
    }
    int v = total_nodes - 1;
    if (flow[v] == 0) return 0;
    int total_flow = flow[v];
    while (v != 0) {
        int u = parent[v];
        cap[u][v] -= total_flow; cap[v][u] += total_flow;
        v = u;
    }
    return total_flow;
}

int main()
{
    scanf("%d %d", &n, &t);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            scanf(" %c", &grid[i][j]);
            if (grid[i][j] == 'Z') { start_i = i; start_j = j; }
        }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            scanf(" %c", &backup[i][j]);
    first_bfs();
    total_nodes = 2 * n * n + 2;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) if (isdigit(grid[i][j]) && grid[i][j] > '0') {
            int v = i * n + j + 1; cap[0][v] = grid[i][j] - '0'; adj_list[0].push_back(v); adj_list[v].push_back(0);
            second_bfs(i, j);
            for (int i2 = 0; i2 < n; i2++)
                for (int j2 = 0; j2 < n; j2++) if (can_reach[i2][j2] && isdigit(backup[i2][j2]) && backup[i2][j2] > '0') {
                    int u = n * n + i2 * n + j2 + 1; cap[v][u] = INF_CONST; adj_list[v].push_back(u); adj_list[u].push_back(v);
                }
        }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) if (isdigit(backup[i][j]) && backup[i][j] > '0') {
            int u = n * n + i * n + j + 1; cap[u][total_nodes - 1] = backup[i][j] - '0'; adj_list[u].push_back(total_nodes - 1); adj_list[total_nodes - 1].push_back(u);
        }
    int flow;
    int total_flow_value = 0;
    while ((flow = max_flow()) != 0) total_flow_value += flow;
    printf("%d\n", total_flow_value);
    return 0;
}
